WITH exploded AS (SELECT id, plan, effective_from, EXPLODE(discounts) AS val FROM price_tiers) SELECT DATE_TRUNC('QUARTER', effective_from) AS quarter_start, CASE WHEN val >= 64 THEN 'HIGH' ELSE 'LOW' END AS val_tier, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(val, 0.5) AS val_p50, COUNT(DISTINCT plan) AS distinct_plans FROM exploded GROUP BY CUBE (DATE_TRUNC('QUARTER', effective_from), CASE WHEN val >= 64 THEN 'HIGH' ELSE 'LOW' END) ORDER BY distinct_plans DESC
